const body = $json.body || $json;

if (!body.partner_vat && !body.partner_name && !body.partner_id) {
  return [{
    json: {
      is_valid: false,
      error_code: 'MISSING_PARTNER',
      error_message: 'Debe especificar al menos partner_vat, partner_name o partner_id',
      raw_body: body
    }
  }];
}

const lines = Array.isArray(body.lines) ? body.lines : [];
if (lines.length === 0) {
  return [{
    json: {
      is_valid: false,
      error_code: 'EMPTY_LINES',
      error_message: 'La orden debe contener al menos una línea de producto en "lines"',
      raw_body: body
    }
  }];
}

let totalEstimated = 0;
const productCodes = [];

const normalizedLines = lines.map((line, idx) => {
  const qty = parseFloat(line.quantity || line.product_qty || 1);
  const price = parseFloat(line.price_unit || line.price || 0);
  const subtotal = qty * price;
  totalEstimated += subtotal;
  const pCode = String(line.product_code || line.default_code || line.barcode || '').trim();
  if (pCode) productCodes.push(pCode);

  return {
    index: idx + 1,
    product_code: pCode,
    barcode: String(line.barcode || '').trim(),
    product_name: String(line.product_name || line.name || 'Producto').trim(),
    product_qty: qty,
    price_unit: price,
    subtotal: subtotal,
    lot_number: String(line.lot_number || line.lote || '').trim(),
    expiration_date: String(line.expiration_date || line.caducidad || '').trim()
  };
});

const dbName = $env.ODOO_DB;
const dbUser = $env.ODOO_USER;
const dbPass = $env.ODOO_PASSWORD;
const botToken = $env.TELEGRAM_BOT_TOKEN;
const defaultChatId = $env.TELEGRAM_CHAT_ID;
const threadCompras = '6';
const threadVariacionPrecios = '7';

const authXml = `<?xml version="1.0"?>
<methodCall>
  <methodName>authenticate</methodName>
  <params>
    <param><value><string>${dbName}</string></value></param>
    <param><value><string>${dbUser}</string></value></param>
    <param><value><string>${dbPass}</string></value></param>
    <param><value><struct></struct></value></param>
  </params>
</methodCall>`;

return [{
  json: {
    is_valid: true,
    stage: 'dev_testing',
    is_dev_testing: true,
    auto_confirm: body.auto_confirm !== false,
    auto_receive: body.auto_receive !== false,
    odoo_db: dbName,
    odoo_user: dbUser,
    odoo_password: dbPass,
    telegram_bot_token: botToken,
    telegram_chat_id: defaultChatId,
    telegram_thread_compras: threadCompras,
    telegram_thread_variacion_precios: threadVariacionPrecios,
    auth_xml: authXml,
    partner_vat: (body.partner_vat || '').trim().toUpperCase(),
    partner_name: (body.partner_name || '').trim(),
    partner_ref: (body.partner_ref || body.folio || '').trim(),
    date_order: body.date_order || new Date().toISOString().split('T')[0],
    note: `[PRUEBAS DEV MIGRACION] ${body.notes || body.note || 'Orden creada via RPA n8n'} (Base: ${dbName})`,
    origin: 'RPA n8n (DEV)',
    lines: normalizedLines,
    product_codes: productCodes,
    total_estimated: totalEstimated,
    total_lines: normalizedLines.length,
    raw_body: body
  }
}];

