const duplicateXml = $json.data || JSON.stringify($json);
const productsRawXml = $('Buscar Productos Odoo').first().json.data || JSON.stringify($('Buscar Productos Odoo').first().json);
const lotsRawXml = $('Preload Lotes Batch').first().json.data || JSON.stringify($('Preload Lotes Batch').first().json);
const context = $('Preparar Preload Lotes').first().json;

// 1. Verificar Duplicados
const dupIdMatch = duplicateXml.match(/<name>id<\/name>\s*<value>(?:<int>|<i4>)(\d+)(?:<\/int>|<\/i4>)<\/value>/);
const dupNameMatch = duplicateXml.match(/<name>name<\/name>\s*<value><string>([^<]+)<\/string><\/value>/);
const dupStateMatch = duplicateXml.match(/<name>state<\/name>\s*<value><string>([^<]+)<\/string><\/value>/);
const dupTotalMatch = duplicateXml.match(/<name>amount_total<\/name>\s*<value>(?:<double>|<int>|<i4>)([\d\.]+)(?:<\/double>|<\/int>|<\/i4>)<\/value>/);

if (dupIdMatch && context.partner_ref) {
  const dupId = parseInt(dupIdMatch[1], 10);
  const odooBaseUrl = 'https://odoo.bodegademedicamentos.com';
  return [{
    json: {
      is_duplicate: true,
      po_id: dupId,
      po_name: dupNameMatch ? dupNameMatch[1] : `PO${dupId}`,
      po_url: `${odooBaseUrl}/odoo/purchase/${dupId}`,
      partner: context.partner_display_name,
      partner_ref: context.partner_ref,
      state: dupStateMatch ? dupStateMatch[1] : 'draft',
      amount_total: dupTotalMatch ? parseFloat(dupTotalMatch[1]) : context.total_estimated,
      notice: 'DUPLICADO DETECTADO: Ya existe una orden de compra registrada con este folio de proveedor.'
    }
  }];
}

// 2. Mapear Productos existentes
const productMap = {};
const productRegex = /<struct>([\s\S]*?)<\/struct>/g;
let pMatch;
while ((pMatch = productRegex.exec(productsRawXml)) !== null) {
  const s = pMatch[1];
  const idM = s.match(/<name>id<\/name>\s*<value>(?:<int>|<i4>)(\d+)(?:<\/int>|<\/i4>)<\/value>/);
  const codeM = s.match(/<name>default_code<\/name>\s*<value><string>([^<]+)<\/string><\/value>/);
  const nameM = s.match(/<name>name<\/name>\s*<value><string>([^<]+)<\/string><\/value>/);
  const priceM = s.match(/<name>list_price<\/name>\s*<value>(?:<double>|<int>|<i4>)([\d\.]+)(?:<\/double>|<\/int>|<\/i4>)<\/value>/);
  if (idM && codeM) {
    productMap[codeM[1].trim()] = {
      id: parseInt(idM[1], 10),
      name: nameM ? nameM[1] : 'Producto',
      list_price: priceM ? parseFloat(priceM[1]) : 0
    };
  }
}

function compactLot(value) {
  let n = (value || '').trim().toUpperCase();
  if (!n) return '';
  n = n.replace(/^(?:LOTE|LT|LOT|L|NO|NUM|#|LOTE:)\s*[-:]*\s*/i, '');
  n = n.replace(/[\s\-_\/\\\.:,]/g, '');
  if (/^\d+$/.test(n)) {
    n = n.replace(/^0+/, '') || '0';
  }
  return n;
}

const lotsByProduct = {};
let lMatch;
while ((lMatch = productRegex.exec(lotsRawXml)) !== null) {
  const s = lMatch[1];
  const idM = s.match(/<name>id<\/name>\s*<value>(?:<int>|<i4>)(\d+)(?:<\/int>|<\/i4>)<\/value>/);
  const nameM = s.match(/<name>name<\/name>\s*<value><string>([^<]+)<\/string><\/value>/);
  const expM = s.match(/<name>expiration_date<\/name>\s*<value>(?:<string>|<dateTime.iso8601>)([^<]+)(?:<\/string>|<\/dateTime.iso8601>)<\/value>/);
  const prodM = s.match(/<name>product_id<\/name>[\s\S]*?<value>(?:<int>|<i4>)(\d+)(?:<\/int>|<\/i4>)<\/value>/);
  if (idM && nameM && prodM) {
    const pId = parseInt(prodM[1], 10);
    const lName = nameM[1].trim();
    if (!lotsByProduct[pId]) lotsByProduct[pId] = [];
    lotsByProduct[pId].push({
      id: parseInt(idM[1], 10),
      name: lName,
      compact: compactLot(lName),
      expiration_date: expM ? expM[1] : ''
    });
  }
}

const priceVariations = [];
const lotsResolved = [];

const orderLinesXml = context.lines.map(line => {
  const matched = productMap[line.product_code] || productMap[line.barcode];
  const prodId = matched ? matched.id : 8286;
  let prodName = (line.product_name || (matched ? matched.name : 'Producto'));

  const inputLot = line.lot_number || '';
  let expDate = line.expiration_date || '';
  let lotId = false;
  let matchType = 'none';

  if (inputLot) {
    const pLots = lotsByProduct[prodId] || [];
    const targetCompact = compactLot(inputLot);

    const exact = pLots.find(l => l.name.toLowerCase() === inputLot.toLowerCase());
    if (exact) {
      lotId = exact.id;
      matchType = 'exact';
      if (!expDate && exact.expiration_date) expDate = exact.expiration_date;
    } else {
      const comp = pLots.find(l => l.compact === targetCompact);
      if (comp) {
        lotId = comp.id;
        matchType = 'compact_fuzzy';
        if (!expDate && comp.expiration_date) expDate = comp.expiration_date;
      } else if (targetCompact.length >= 4) {
        const sub = pLots.find(l => l.compact.length >= 4 && (l.compact.includes(targetCompact) || targetCompact.includes(l.compact)));
        if (sub) {
          lotId = sub.id;
          matchType = 'substring_fuzzy';
          if (!expDate && sub.expiration_date) expDate = sub.expiration_date;
        }
      }
    }

    lotsResolved.push({
      product_id: prodId,
      product_name: prodName,
      input_lot: inputLot,
      resolved_lot_id: lotId,
      match_type: matchType,
      inherited_expiration_date: expDate
    });

    prodName += ` [Lote: ${inputLot}${expDate ? ' | Cad: ' + expDate : ''}]`;
  }

  const listPrice = matched ? matched.list_price : 0;
  if (listPrice > 0 && Math.abs(line.price_unit - listPrice) > 0.01) {
    const deltaPct = ((line.price_unit - listPrice) / listPrice) * 100;
    priceVariations.push({
      product_id: prodId,
      product_name: prodName,
      old_price: listPrice,
      new_price: line.price_unit,
      delta_pct: parseFloat(deltaPct.toFixed(2)),
      direction: deltaPct > 0 ? 'up' : 'down'
    });
  }

  const safeProdName = prodName.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
  let lineMembers = `
    <member><name>product_id</name><value><int>${prodId}</int></value></member>
    <member><name>name</name><value><string>${safeProdName}</string></value></member>
    <member><name>product_qty</name><value><double>${line.product_qty}</double></value></member>
    <member><name>price_unit</name><value><double>${line.price_unit}</double></value></member>`;

  if (lotId) {
    lineMembers += `
    <member><name>lot_id</name><value><int>${lotId}</int></value></member>`;
  }
  if (expDate) {
    const safeExp = expDate.includes(' ') ? expDate : `${expDate} 00:00:00`;
    lineMembers += `
    <member><name>lot_expiration_date</name><value><string>${safeExp}</string></value></member>`;
  }

  return `
    <value>
      <array>
        <data>
          <value><int>0</int></value>
          <value><int>0</int></value>
          <value>
            <struct>${lineMembers}</struct>
          </value>
        </data>
      </array>
    </value>`;
}).join('');

const createPoXml = `<?xml version="1.0"?>
<methodCall>
  <methodName>execute_kw</methodName>
  <params>
    <param><value><string>${context.odoo_db}</string></value></param>
    <param><value><int>${context.odoo_uid}</int></value></param>
    <param><value><string>${context.odoo_password}</string></value></param>
    <param><value><string>purchase.order</string></value></param>
    <param><value><string>create</string></value></param>
    <param>
      <value>
        <array>
          <data>
            <value>
              <struct>
                <member><name>partner_id</name><value><int>${context.partner_id}</int></value></member>
                <member><name>partner_ref</name><value><string>${context.partner_ref || ''}</string></value></member>
                <member><name>origin</name><value><string>${context.origin || 'RPA n8n'}</string></value></member>
                <member><name>note</name><value><string>${context.note || ''}</string></value></member>
                <member>
                  <name>order_line</name>
                  <value><array><data>${orderLinesXml}</data></array></value>
                </member>
              </struct>
            </value>
          </data>
        </array>
      </value>
    </param>
  </params>
</methodCall>`;

return [{
  json: {
    ...context,
    is_duplicate: false,
    price_variations: priceVariations,
    lots_resolved: lotsResolved,
    create_po_xml: createPoXml
  }
}];

