const rawXml = $json.data || $json.body || JSON.stringify($json);
const match = rawXml.match(/<int>(\d+)<\/int>/) || rawXml.match(/<i4>(\d+)<\/i4>/);
const poId = match ? parseInt(match[1], 10) : null;

const prev = $('Resolver Lotes y Precios').first().json;

const autoConfirmXml = poId ? `<?xml version="1.0"?>
<methodCall>
  <methodName>execute_kw</methodName>
  <params>
    <param><value><string>${prev.odoo_db}</string></value></param>
    <param><value><int>${prev.odoo_uid}</int></value></param>
    <param><value><string>${prev.odoo_password}</string></value></param>
    <param><value><string>purchase.order</string></value></param>
    <param><value><string>button_confirm</string></value></param>
    <param>
      <value>
        <array>
          <data>
            <value>
              <array>
                <data>
                  <value><int>${poId}</int></value>
                </data>
              </array>
            </value>
          </data>
        </array>
      </value>
    </param>
  </params>
</methodCall>` : '';

const notifXmls = (prev.price_variations || []).map(v => `
<value>
  <struct>
    <member><name>product_id</name><value><int>${v.product_id}</int></value></member>
    <member><name>product_name</name><value><string>${v.product_name}</string></value></member>
    <member><name>partner_id</name><value><int>${prev.partner_id}</int></value></member>
    <member><name>old_price</name><value><double>${v.old_price}</double></value></member>
    <member><name>new_price</name><value><double>${v.new_price}</double></value></member>
    <member><name>delta_pct</name><value><double>${v.delta_pct}</double></value></member>
    <member><name>direction</name><value><string>${v.direction}</string></value></member>
    <member><name>purchase_order_id</name><value><int>${poId || 1}</int></value></member>
    <member><name>state</name><value><string>unread</string></value></member>
  </struct>
</value>`).join('');

const createNotifsXml = notifXmls ? `<?xml version="1.0"?>
<methodCall>
  <methodName>execute_kw</methodName>
  <params>
    <param><value><string>${prev.odoo_db}</string></value></param>
    <param><value><int>${prev.odoo_uid}</int></value></param>
    <param><value><string>${prev.odoo_password}</string></value></param>
    <param><value><string>purchase.price.notification</string></value></param>
    <param><value><string>create</string></value></param>
    <param>
      <value>
        <array>
          <data>${notifXmls}</data>
        </array>
      </value>
    </param>
  </params>
</methodCall>` : '';

const hasPriceVariations = (prev.price_variations || []).length > 0;
const tgMessageThreadId = hasPriceVariations
  ? (prev.telegram_thread_variacion_precios || prev.telegram_thread_compras)
  : prev.telegram_thread_compras;

const odooBaseUrl = 'https://odoo.bodegademedicamentos.com';
const poUrl = poId ? `${odooBaseUrl}/odoo/purchase/${poId}` : odooBaseUrl;

// Construir mensaje enriquecido para Telegram (Estilo Tarjeta Ejecutiva)
let tgMsg = `━━━━━━━━━━━━━━━━━━━━━━\n`;
tgMsg += `🏢 <b>MEDICINE DEPOT</b> | <b>ORDEN DE COMPRA</b>\n`;
tgMsg += `━━━━━━━━━━━━━━━━━━━━━━\n`;
tgMsg += `🟢 <b>Estado:</b> <code>${prev.auto_confirm ? 'CONFIRMADA (purchase)' : 'PRESUPUESTO (draft)'}</code>\n`;
tgMsg += `📄 <b>Folio OC:</b> <code>PO${poId}</code> (ID: #${poId})\n`;
tgMsg += `🚚 <b>Proveedor:</b> <b>${prev.partner_display_name}</b>\n`;
tgMsg += `📑 <b>Folio Prov:</b> <code>${prev.partner_ref || 'N/A'}</code>\n`;
tgMsg += `💵 <b>Total Estimado:</b> <code>$${prev.total_estimated.toLocaleString('es-MX', {minimumFractionDigits: 2})} MXN</code>\n`;
tgMsg += `📦 <b>Partidas:</b> <code>${prev.total_lines} productos</code>\n`;

if (prev.lots_resolved && prev.lots_resolved.length > 0) {
  tgMsg += `\n━━━━━━━━━━━━━━━━━━━━━━\n`;
  tgMsg += `📦 <b>TRAZABILIDAD DE LOTES ASIGNADOS</b>\n`;
  tgMsg += `━━━━━━━━━━━━━━━━━━━━━━\n`;
  prev.lots_resolved.forEach(l => {
    const exp = l.inherited_expiration_date ? l.inherited_expiration_date.split(' ')[0] : 'S/F';
    const prodLabel = l.product_name ? l.product_name.split('[')[0].trim() : 'Producto';
    tgMsg += `▫️ <b>${prodLabel}</b>\n`;
    tgMsg += `   🏷️ Lote: <code>${l.input_lot}</code> | ⏳ Cad: <code>${exp}</code> [${l.match_type}]\n`;
  });
}

if (prev.price_variations && prev.price_variations.length > 0) {
  tgMsg += `\n━━━━━━━━━━━━━━━━━━━━━━\n`;
  tgMsg += `⚠️ <b>AUDITORÍA DE PRECIOS</b>\n`;
  tgMsg += `━━━━━━━━━━━━━━━━━━━━━━\n`;
  prev.price_variations.forEach(pv => {
    const icon = pv.direction === 'up' ? '🔺' : '🔻';
    const pLabel = pv.product_name.split('[')[0].trim();
    tgMsg += `${icon} <b>${pLabel}:</b> <b>${pv.delta_pct > 0 ? '+' : ''}${pv.delta_pct}%</b> (<code>$${pv.old_price}</code> ➔ <code>$${pv.new_price}</code>)\n`;
  });
}

tgMsg += `\n━━━━━━━━━━━━━━━━━━━━━━\n`;
tgMsg += `🤖 <i>RPA Bot • Sincronizado con Odoo Dev 19</i>`;

const tgMarkup = {
  inline_keyboard: [
    [
      {"text": "🔗 Ver en Odoo", "url": poUrl},
      {"text": "📦 Albarán Stock", "url": "https://odoo.bodegademedicamentos.com/odoo/action-stock.action_picking_tree_all"}
    ]
  ]
};

return [{
  json: {
    success: !!poId,
    po_id: poId,
    po_url: poUrl,
    auto_confirm: prev.auto_confirm,
    auto_confirm_xml: autoConfirmXml,
    create_notifs_xml: createNotifsXml,
    telegram_bot_token: prev.telegram_bot_token,
    tg_chat_id: prev.telegram_chat_id,
    tg_message_thread_id: tgMessageThreadId,
    tg_text: tgMsg,
    tg_reply_markup: JSON.stringify(tgMarkup),
    price_variations: prev.price_variations,
    lots_resolved: prev.lots_resolved,
    partner: prev.partner_display_name,
    partner_ref: prev.partner_ref,
    total_estimated: prev.total_estimated,
    total_lines: prev.total_lines,
    has_price_notifications: (prev.price_variations || []).length > 0
  }
}];

